// PRIMARY: ethereum/statetransition/src/main/java/tech/pegasys/teku/statetransition/validation/BlockGossipValidator.java:internalValidate (lines 202-222)
// Teku (consensus layer) does NOT verify receipt bloom consistency with logs.
// It delegates execution validation entirely to the EL client via Engine API.
// The receiptsRoot is included in the ExecutionPayloadHeader but Teku only stores
// it as received — no bloom-vs-log cross-check is performed here.
if (miscHelpers.isMergeTransitionComplete(postState)) {
  Optional<ExecutionPayload> executionPayload =
      block.getMessage().getBody().getOptionalExecutionPayload();
  if (executionPayload.isEmpty()) {
    return reject("Missing execution payload");
  }
  // Only timestamp is checked, NOT receiptsRoot or logsBloom consistency
  if (executionPayload.get().getTimestamp()
      .compareTo(spec.computeTimeAtSlot(postState, block.getSlot())) != 0) {
    return reject("Execution Payload timestamp is not consistence with and block slot time");
  }
}

