// PRIMARY: ethereum/executionlayer/src/main/java/tech/pegasys/teku/ethereum/executionlayer/BuilderBidValidatorImpl.java:validateBuilderBid (lines 118-129)
// Gas limit validation in Teku is advisory (logs warning, not rejection):
final UInt64 parentGasLimit =
    state.toVersionBellatrix().orElseThrow().getLatestExecutionPayloadHeader().getGasLimit();
final UInt64 preferredGasLimit = validatorRegistration.getGasLimit();
final UInt64 proposedGasLimit = executionPayloadHeader.getGasLimit();
final UInt64 expectedGasLimit = expectedGasLimit(parentGasLimit, preferredGasLimit);
if (!expectedGasLimit.equals(proposedGasLimit)) {
  // Only a warning log — NOT a rejection!
  eventLogger.builderBidNotHonouringGasLimit(parentGasLimit, proposedGasLimit, expectedGasLimit, preferredGasLimit);
}
// NOTE: gas_used <= gas_limit enforcement is delegated to the EL client (Engine API).

