// PRIMARY: ethereum/spec/src/main/java/tech/pegasys/teku/spec/logic/versions/bellatrix/block/BlockProcessorBellatrix.java:processExecutionPayload (lines 119-131)
// Teku calls the EL via Engine API (optimistic execution) for state_root verification.
// The EL is responsible for executing transactions and verifying state_root.
// Teku stores the executionPayloadHeader (including stateRoot) and trusts the EL
// response (VALID/INVALID) to determine if state_root is correct:
public void processExecutionPayload(...) throws BlockProcessingException {
  validateExecutionPayload(genericState, beaconBlockBody, payloadExecutor);
  final MutableBeaconStateBellatrix state = MutableBeaconStateBellatrix.required(genericState);
  final ExecutionPayloadHeader executionPayloadHeader = extractExecutionPayloadHeader(beaconBlockBody);
  state.setLatestExecutionPayloadHeader(executionPayloadHeader);
}
